<script setup lang="ts">
import {localize,localizeRecord} from './localization';
import { computed } from 'vue';
import { useSession } from './store';
import { issueMessages } from './i18n';
import type { JobSummary } from '../../../packages/schema/index';
const props=defineProps<{language:'zh'|'en'}>();const emit=defineEmits<{select:[id:string]}>();const store=useSession();
const text=computed(()=>localizeRecord(props.language==='zh'?{empty:'还没有计算任务。选择纸样，在缝份属性中生成候选。',accept:'采用结果',cancel:'取消计算',discard:'丢弃候选',queued:'排队中',running:'计算中',succeeded:'候选待采用',failed:'失败',cancelled:'已取消',accepted:'已采用',discarded:'已丢弃',stale:'已过期，请重新计算',base:'来源版本',width:'候选缝份'}:{empty:'No calculations yet. Select a pattern and generate an allowance candidate.',accept:'Accept result',cancel:'Cancel',discard:'Discard',queued:'Queued',running:'Running',succeeded:'Candidate ready',failed:'Failed',cancelled:'Cancelled',accepted:'Accepted',discarded:'Discarded',stale:'Stale: recalculate',base:'Base revision',width:'Candidate allowance'}));
async function action(job:JobSummary,kind:'accept'|'cancel'|'discard'){const p=store.data.project;if(!p)return;await store.run(()=>kind==='accept'?window.fpcad.acceptResult(p.id,p.revision,job.id,job.resultHash!):kind==='cancel'?window.fpcad.cancelJob(p.id,p.revision,job.id):window.fpcad.discardResult(p.id,p.revision,job.id));}
</script>
<template><p v-if="!store.data.jobs.length" class="jobs-empty">{{text.empty}}</p><div v-for="job in store.data.jobs" :key="job.id" class="job-row"><button class="job-name" @click="emit('select',job.pieceId)">{{job.pieceName}}<small>{{text.width}} {{job.distanceMm}} mm · {{text.base}} {{job.baseRevision}}</small></button><span :class="['job-status',job.status]">{{text[job.status]}}</span><div class="spacer"></div><button v-if="job.status==='queued'||job.status==='running'" :disabled="store.busy" @click="action(job,'cancel')">{{text.cancel}}</button><button v-if="job.status==='succeeded'" class="primary" :disabled="store.busy" @click="action(job,'accept')">{{text.accept}}</button><button v-if="['succeeded','stale','failed','cancelled'].includes(job.status)" :disabled="store.busy" @click="action(job,'discard')">{{text.discard}}</button><div v-if="job.issues.length" class="job-issues"><span v-for="issue in job.issues" :key="issue.ruleId">{{localize(issueMessages[issue.messageKey]?.[language==='zh'?0:1]??issue.messageKey)}}</span></div><small v-else-if="job.errorCode&&job.errorCode!=='CANCELLED'" class="error">{{job.errorCode}}</small></div></template>
<style scoped>.jobs-empty{font-size:11px;color:var(--accent)}.job-row{display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:7px 0;border-bottom:1px solid var(--border)}.job-row button{font-size:11px;padding:5px 8px}.job-name{background:transparent;border:0;text-align:left;min-width:160px}.job-name small{display:block;color:var(--accent);font-size:10px;margin-top:4px}.job-status{font-size:11px;color:var(--accent)}.job-status.succeeded,.job-status.accepted{color:var(--accent)}.job-status.failed,.job-status.stale{color:var(--warning)}.job-issues{width:100%;font-size:11px;color:var(--warning)}.job-issues span{display:block}</style>
